sources.cmd:
p=$HATCH_ARG
case "$p" in /*) ;; *) echo '@@err not an absolute path'; exit 0;; esac
[ -e "$p" ] || { echo '@@err no such folder (it may have been moved or deleted)'; exit 0; }
[ -d "$p" ] || { echo '@@err not a folder'; exit 0; }
[ -r "$p" ] && [ -x "$p" ] || { echo '@@err permission denied'; exit 0; }
r=$(cd -- "$p" 2>/dev/null && pwd -P) || { echo '@@err cannot open this folder'; exit 0; }
echo "@@real $r"; echo @@entries
find "$r" -mindepth 1 -maxdepth 1 -printf '%y%Y\037%s\037%T@\037%l\037%f\0' 2>/dev/null | head -z -n 3001
true
